/* ============================================================
   DESIGN TOKENS
   ============================================================ */
:root {
  /* Colors */
  --color-bg:           #0d0d0f;
  --color-surface:      #141418;
  --color-surface-2:    #1c1c22;
  --color-surface-3:    #252530;
  --color-border:       #2e2e3a;
  --color-border-light: #3d3d4e;

  --color-text:         #f0f0f5;
  --color-text-muted:   #9898ae;
  --color-text-faint:   #5c5c72;

  --color-accent:       #7c6af7;
  --color-accent-hover: #9585ff;
  --color-accent-press: #6454e0;
  --color-accent-dim:   rgba(124, 106, 247, 0.15);

  --color-gold:         #f5c842;
  --color-gold-dim:     rgba(245, 200, 66, 0.12);
  --color-red:          #e8485a;
  --color-green:        #3ecf8e;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Inter', system-ui, sans-serif;

  --text-xs:   0.75rem;
  --text-sm:   0.875rem;
  --text-base: 1rem;
  --text-lg:   1.125rem;
  --text-xl:   1.25rem;
  --text-2xl:  1.5rem;
  --text-3xl:  1.875rem;
  --text-4xl:  2.25rem;
  --text-5xl:  3rem;
  --text-6xl:  3.75rem;

  --weight-regular: 400;
  --weight-medium:  500;
  --weight-semi:    600;
  --weight-bold:    700;

  /* Spacing */
  --space-1:  0.25rem;
  --space-2:  0.5rem;
  --space-3:  0.75rem;
  --space-4:  1rem;
  --space-5:  1.25rem;
  --space-6:  1.5rem;
  --space-8:  2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Radii */
  --radius-sm:   6px;
  --radius-md:   10px;
  --radius-lg:   16px;
  --radius-xl:   24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm:  0 1px 3px rgba(0,0,0,0.4), 0 1px 2px rgba(0,0,0,0.3);
  --shadow-md:  0 4px 12px rgba(0,0,0,0.5), 0 2px 4px rgba(0,0,0,0.3);
  --shadow-lg:  0 10px 30px rgba(0,0,0,0.6), 0 4px 8px rgba(0,0,0,0.3);
  --shadow-glow: 0 0 20px rgba(124,106,247,0.3);

  /* Layout */
  --container-max: 1280px;
  --container-pad: clamp(1rem, 5vw, 2.5rem);

  /* Motion */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --dur-fast: 150ms;
  --dur-base: 250ms;
  --dur-slow: 400ms;
}

/* ============================================================
   RESET & BASE
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.6;
  min-height: 100dvh;
  overflow-x: hidden;
}

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ============================================================
   SKIP LINK
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-4);
  z-index: 9999;
  background: var(--color-accent);
  color: #fff;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  font-weight: var(--weight-semi);
  font-size: var(--text-sm);
  transition: top var(--dur-fast);
}
.skip-link:focus { top: var(--space-4); }

/* ============================================================
   UTILITY
   ============================================================ */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-pad);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
  flex-wrap: wrap;
}

.section-title {
  font-size: var(--text-2xl);
  font-weight: var(--weight-bold);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.section-title span {
  color: var(--color-accent);
}

.view-all-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-accent);
  transition: color var(--dur-fast);
  white-space: nowrap;
}
.view-all-link:hover { color: var(--color-accent-hover); }
.view-all-link svg { transition: transform var(--dur-fast) var(--ease-out); }
.view-all-link:hover svg { transform: translateX(3px); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px var(--space-2);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  letter-spacing: 0.03em;
  line-height: 1.4;
}
.badge--new     { background: var(--color-accent-dim); color: var(--color-accent-hover); }
.badge--sale    { background: rgba(232, 72, 90, 0.15); color: #ff7585; }
.badge--hot     { background: rgba(245, 200, 66, 0.15); color: var(--color-gold); }
.badge--limited { background: rgba(62, 207, 142, 0.15); color: var(--color-green); }

/* ============================================================
   ANNOUNCEMENT BAR
   ============================================================ */
.announcement-bar {
  background: var(--color-accent);
  color: #fff;
  text-align: center;
  padding: var(--space-2) var(--container-pad);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  letter-spacing: 0.01em;
}
.announcement-bar a {
  text-decoration: underline;
  text-underline-offset: 2px;
}
.announcement-bar a:hover { opacity: 0.85; }

/* ============================================================
   HEADER / NAV
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 13, 15, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: var(--space-4);
  padding-block: var(--space-4);
}

/* Logo */
.site-logo {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  letter-spacing: -0.03em;
  color: var(--color-text);
  transition: opacity var(--dur-fast);
}
.site-logo:hover { opacity: 0.8; }
.logo-mark {
  width: 32px; height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.logo-mark svg { color: #fff; }

/* Primary nav */
.primary-nav { justify-self: center; }
.primary-nav ul {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}
.primary-nav a {
  display: inline-block;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-text-muted);
  transition: color var(--dur-fast), background var(--dur-fast);
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-2);
}
.primary-nav a[aria-current="page"] { color: var(--color-accent); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  justify-self: end;
}

.header-search {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: var(--space-2) var(--space-4);
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
  width: min(240px, 30vw);
}
.header-search:focus-within {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent-dim);
}
.header-search svg { color: var(--color-text-faint); flex-shrink: 0; }
.header-search input {
  background: none;
  border: none;
  outline: none;
  color: var(--color-text);
  font-size: var(--text-sm);
  font-family: inherit;
  width: 100%;
}
.header-search input::placeholder { color: var(--color-text-faint); }

.icon-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  color: var(--color-text-muted);
  transition: color var(--dur-fast), background var(--dur-fast);
}
.icon-btn:hover { color: var(--color-text); background: var(--color-surface-2); }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-full);
  font-size: 10px;
  font-weight: var(--weight-bold);
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  color: var(--color-text-muted);
  transition: background var(--dur-fast);
}
.menu-toggle:hover { background: var(--color-surface-2); }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  padding-block: var(--space-20) var(--space-24);
  background: var(--color-bg);
}

.hero-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.hero-bg-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 60% 40%, rgba(124,106,247,0.18) 0%, transparent 70%),
    radial-gradient(ellipse 40% 40% at 20% 80%, rgba(62,207,142,0.08) 0%, transparent 60%);
}

.hero-grid-lines {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 0%, transparent 100%);
}

.hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-5);
}
.hero-eyebrow::before {
  content: '';
  width: 20px; height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.hero-title {
  font-size: clamp(var(--text-4xl), 5.5vw, var(--text-6xl));
  font-weight: var(--weight-bold);
  letter-spacing: -0.03em;
  line-height: 1.07;
  margin-bottom: var(--space-6);
}

.hero-title .highlight {
  background: linear-gradient(135deg, var(--color-accent) 0%, #b89bff 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-desc {
  font-size: var(--text-lg);
  color: var(--color-text-muted);
  line-height: 1.7;
  max-width: 44ch;
  margin-bottom: var(--space-8);
}

.hero-ctas {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  font-weight: var(--weight-semi);
  line-height: 1;
  transition: all var(--dur-fast) var(--ease-out);
  white-space: nowrap;
  border: 2px solid transparent;
}
.btn--primary {
  background: var(--color-accent);
  color: #fff;
}
.btn--primary:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 16px rgba(124,106,247,0.4);
  transform: translateY(-1px);
}
.btn--primary:active { background: var(--color-accent-press); transform: none; }

.btn--ghost {
  background: transparent;
  color: var(--color-text);
  border-color: var(--color-border-light);
}
.btn--ghost:hover {
  background: var(--color-surface-2);
  border-color: var(--color-border-light);
}

.btn--lg { padding: var(--space-4) var(--space-8); font-size: var(--text-base); }

.hero-stats {
  display: flex;
  gap: var(--space-8);
  margin-top: var(--space-10);
  padding-top: var(--space-8);
  border-top: 1px solid var(--color-border);
}
.hero-stat-value {
  font-size: var(--text-2xl);
  font-weight: var(--weight-bold);
  letter-spacing: -0.02em;
  color: var(--color-text);
}
.hero-stat-label {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  margin-top: 2px;
}

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-product-card {
  position: relative;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-lg), 0 0 60px rgba(124,106,247,0.12);
  width: 100%;
  max-width: 380px;
}

.hero-product-image {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-lg);
  background: linear-gradient(145deg, var(--color-surface-2) 0%, var(--color-surface-3) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  overflow: hidden;
  position: relative;
}

.hero-product-image svg {
  opacity: 0.4;
}

.hero-product-image-decor {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 60% 30%, rgba(124,106,247,0.25) 0%, transparent 60%);
}

.hero-product-meta { display: flex; flex-direction: column; gap: var(--space-3); }
.hero-product-brand {
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
.hero-product-name {
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  letter-spacing: -0.01em;
}
.hero-product-price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.hero-product-price {
  font-size: var(--text-2xl);
  font-weight: var(--weight-bold);
  color: var(--color-accent);
}
.hero-product-add {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  background: var(--color-accent);
  color: #fff;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  font-weight: var(--weight-semi);
  transition: all var(--dur-fast);
}
.hero-product-add:hover {
  background: var(--color-accent-hover);
  box-shadow: var(--shadow-glow);
}

.hero-float-badge {
  position: absolute;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-3) var(--space-4);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-sm);
  font-weight: var(--weight-semi);
  white-space: nowrap;
}
.hero-float-badge--rating {
  top: -16px;
  right: -20px;
}
.hero-float-badge--shipping {
  bottom: 20px;
  left: -24px;
}
.float-icon {
  width: 32px; height: 32px;
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.float-icon--gold { background: var(--color-gold-dim); color: var(--color-gold); }
.float-icon--green { background: rgba(62,207,142,0.15); color: var(--color-green); }

/* ============================================================
   CATEGORY STRIP
   ============================================================ */
.categories-section {
  padding-block: var(--space-12);
  border-block: 1px solid var(--color-border);
  background: var(--color-surface);
}

.categories-strip {
  display: flex;
  gap: var(--space-3);
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: var(--space-1);
  scroll-snap-type: x mandatory;
}
.categories-strip::-webkit-scrollbar { display: none; }

.category-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-5);
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-text-muted);
  white-space: nowrap;
  transition: all var(--dur-fast);
  scroll-snap-align: start;
  flex-shrink: 0;
}
.category-chip:hover,
.category-chip[aria-pressed="true"] {
  background: var(--color-accent-dim);
  border-color: var(--color-accent);
  color: var(--color-accent-hover);
}
.category-chip[aria-pressed="true"] { font-weight: var(--weight-semi); }

.category-icon {
  font-size: 1.1em;
  line-height: 1;
}

/* ============================================================
   FEATURED PRODUCTS
   ============================================================ */
.featured-section {
  padding-block: var(--space-20);
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-5);
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--dur-base) var(--ease-out), box-shadow var(--dur-base), border-color var(--dur-base);
  position: relative;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-border-light);
}

.product-card-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-surface-2);
  overflow: hidden;
}

.product-card-image {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--dur-slow) var(--ease-out);
}
.product-card:hover .product-card-image { transform: scale(1.04); }

.product-card-badges {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.product-card-wishlist {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  width: 34px; height: 34px;
  background: rgba(13, 13, 15, 0.7);
  backdrop-filter: blur(6px);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: all var(--dur-fast);
  opacity: 0;
  transform: scale(0.8);
}
.product-card:hover .product-card-wishlist,
.product-card-wishlist:focus-visible {
  opacity: 1;
  transform: scale(1);
}
.product-card-wishlist:hover,
.product-card-wishlist[aria-pressed="true"] {
  color: var(--color-red);
  background: rgba(232, 72, 90, 0.15);
}

.product-card-quick-add {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  background: rgba(13, 13, 15, 0.9);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-3);
  transform: translateY(100%);
  transition: transform var(--dur-base) var(--ease-out);
}
.product-card:hover .product-card-quick-add,
.product-card:focus-within .product-card-quick-add {
  transform: translateY(0);
}
.quick-add-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  background: var(--color-accent);
  color: #fff;
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  font-weight: var(--weight-semi);
  transition: background var(--dur-fast);
  width: 100%;
  justify-content: center;
}
.quick-add-btn:hover { background: var(--color-accent-hover); }

.product-card-body {
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  flex: 1;
}

.product-card-brand {
  font-size: var(--text-xs);
  color: var(--color-text-faint);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: var(--weight-medium);
}

.product-card-name {
  font-size: var(--text-base);
  font-weight: var(--weight-semi);
  color: var(--color-text);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.product-card-rating {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.stars {
  display: flex;
  gap: 1px;
  color: var(--color-gold);
}
.rating-count {
  font-size: var(--text-xs);
  color: var(--color-text-faint);
}

.product-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--color-border);
  background: var(--color-surface-2);
}

.product-price { display: flex; align-items: baseline; gap: var(--space-2); }
.price-current {
  font-size: var(--text-lg);
  font-weight: var(--weight-bold);
  color: var(--color-text);
}
.price-original {
  font-size: var(--text-sm);
  color: var(--color-text-faint);
  text-decoration: line-through;
}
.price-savings {
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  color: var(--color-red);
}

/* ============================================================
   DEALS SECTION
   ============================================================ */
.deals-section {
  padding-block: var(--space-20);
  background: var(--color-surface);
  border-block: 1px solid var(--color-border);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: var(--space-5);
}

.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: transform var(--dur-base) var(--ease-out), box-shadow var(--dur-base), border-color var(--dur-base);
}
.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-border-light);
}

.deal-card--featured {
  grid-row: span 2;
}

.deal-card-image {
  aspect-ratio: 1;
  background: var(--color-surface-3);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}
.deal-card--featured .deal-card-image { aspect-ratio: auto; flex: 1; min-height: 200px; }

.deal-card-image-decor {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.deal-card-content {
  padding: var(--space-5);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.deal-card--featured .deal-card-content { padding: var(--space-6); }

.deal-label {
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
}

.deal-name {
  font-size: var(--text-base);
  font-weight: var(--weight-semi);
  line-height: 1.35;
}
.deal-card--featured .deal-name { font-size: var(--text-xl); }

.deal-price-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-wrap: wrap;
}
.deal-price {
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  color: var(--color-text);
}
.deal-card--featured .deal-price { font-size: var(--text-3xl); }
.deal-original {
  font-size: var(--text-sm);
  color: var(--color-text-faint);
  text-decoration: line-through;
}
.deal-discount-badge {
  background: rgba(232, 72, 90, 0.18);
  color: #ff7585;
  border-radius: var(--radius-sm);
  padding: 2px var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
}

.deal-countdown {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-xs);
  color: var(--color-text-muted);
}
.countdown-timer {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: var(--text-sm);
  font-weight: var(--weight-bold);
  color: var(--color-gold);
}
.countdown-sep { opacity: 0.5; }

.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  background: var(--color-accent);
  color: #fff;
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  font-weight: var(--weight-semi);
  transition: all var(--dur-fast);
  align-self: flex-start;
  margin-top: var(--space-2);
}
.deal-cta:hover { background: var(--color-accent-hover); box-shadow: var(--shadow-glow); }

/* ============================================================
   EDITORIAL / CONTENT SECTION
   ============================================================ */
.editorial-section {
  padding-block: var(--space-20);
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-5);
}

.editorial-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: border-color var(--dur-base), box-shadow var(--dur-base);
}
.editorial-card:hover {
  border-color: var(--color-border-light);
  box-shadow: var(--shadow-lg);
}

.editorial-card--wide { grid-column: span 2; display: grid; grid-template-columns: 1fr 1fr; }

.editorial-card-image {
  aspect-ratio: 16/10;
  background: var(--color-surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}
.editorial-card--wide .editorial-card-image { aspect-ratio: auto; }

.editorial-card-image-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(13,13,15,0.7) 100%);
}

.editorial-card-content {
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  flex: 1;
}

.editorial-card-eyebrow {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
}

.editorial-card-title {
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  letter-spacing: -0.01em;
  line-height: 1.3;
}
.editorial-card--wide .editorial-card-title { font-size: var(--text-2xl); }

.editorial-card-desc {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  line-height: 1.6;
}

.editorial-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-xs);
  color: var(--color-text-faint);
  margin-top: auto;
  padding-top: var(--space-3);
  border-top: 1px solid var(--color-border);
}
.editorial-card-author-avatar {
  width: 24px; height: 24px;
  border-radius: var(--radius-full);
  background: var(--color-accent-dim);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px;
  font-weight: var(--weight-bold);
  color: var(--color-accent);
  flex-shrink: 0;
}
.editorial-read-more {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--color-accent);
  font-weight: var(--weight-medium);
  transition: gap var(--dur-fast);
}
.editorial-read-more:hover { gap: var(--space-2); }

/* ============================================================
   BRANDS MARQUEE
   ============================================================ */
.brands-section {
  padding-block: var(--space-12);
  border-block: 1px solid var(--color-border);
  overflow: hidden;
}

.brands-label {
  text-align: center;
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-faint);
  margin-bottom: var(--space-6);
}

.brands-track-wrap {
  position: relative;
  overflow: hidden;
}
.brands-track-wrap::before,
.brands-track-wrap::after {
  content: '';
  position: absolute;
  top: 0; bottom: 0;
  width: 120px;
  z-index: 1;
  pointer-events: none;
}
.brands-track-wrap::before { left: 0; background: linear-gradient(to right, var(--color-bg), transparent); }
.brands-track-wrap::after  { right: 0; background: linear-gradient(to left, var(--color-bg), transparent); }

.brands-track {
  display: flex;
  gap: var(--space-12);
  width: max-content;
  animation: marquee 28s linear infinite;
}
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
@media (prefers-reduced-motion: reduce) {
  .brands-track { animation: none; flex-wrap: wrap; justify-content: center; width: 100%; }
}

.brand-item {
  display: flex;
  align-items: center;
  font-size: var(--text-lg);
  font-weight: var(--weight-bold);
  letter-spacing: -0.02em;
  color: var(--color-text-faint);
  transition: color var(--dur-fast);
  white-space: nowrap;
}
.brand-item:hover { color: var(--color-text-muted); }

/* ============================================================
   NEWSLETTER
   ============================================================ */
.newsletter-section {
  padding-block: var(--space-20);
  background: var(--color-surface);
  border-block: 1px solid var(--color-border);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.newsletter-text { display: flex; flex-direction: column; gap: var(--space-4); }

.newsletter-label {
  font-size: var(--text-xs);
  font-weight: var(--weight-semi);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent);
}

.newsletter-title {
  font-size: var(--text-3xl);
  font-weight: var(--weight-bold);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.newsletter-desc {
  font-size: var(--text-base);
  color: var(--color-text-muted);
  line-height: 1.7;
  max-width: 42ch;
}

.newsletter-perks {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-top: var(--space-2);
}
.newsletter-perk {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}
.perk-icon { color: var(--color-green); flex-shrink: 0; }

.newsletter-form { display: flex; flex-direction: column; gap: var(--space-4); }

.form-group { display: flex; flex-direction: column; gap: var(--space-2); }

.form-label {
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-text);
}

.required-mark { color: var(--color-red); margin-left: 2px; }

.form-input {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-base);
  font-family: inherit;
  color: var(--color-text);
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
  width: 100%;
}
.form-input::placeholder { color: var(--color-text-faint); }
.form-input:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent-dim);
}
.form-input[aria-invalid="true"] {
  border-color: var(--color-red);
  box-shadow: 0 0 0 3px rgba(232,72,90,0.15);
}

.form-error {
  font-size: var(--text-xs);
  color: var(--color-red);
  display: none;
}
.form-error[aria-live="polite"] { display: block; }

.form-submit { margin-top: var(--space-2); }

.newsletter-privacy {
  font-size: var(--text-xs);
  color: var(--color-text-faint);
  line-height: 1.5;
}
.newsletter-privacy a {
  color: var(--color-text-muted);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.newsletter-privacy a:hover { color: var(--color-text); }

.form-success {
  display: none;
  background: rgba(62, 207, 142, 0.1);
  border: 1px solid rgba(62, 207, 142, 0.3);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  color: var(--color-green);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
}
.form-success[aria-live="polite"] { display: flex; align-items: center; gap: var(--space-2); }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-block: var(--space-16) var(--space-8);
}

.footer-main {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--space-12);
  margin-bottom: var(--space-12);
  padding-bottom: var(--space-12);
  border-bottom: 1px solid var(--color-border);
}

.footer-brand .site-logo { margin-bottom: var(--space-4); }
.footer-brand-desc {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  line-height: 1.7;
  max-width: 30ch;
  margin-bottom: var(--space-5);
}

.footer-social {
  display: flex;
  gap: var(--space-2);
}
.social-link {
  width: 36px; height: 36px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-text-muted);
  transition: all var(--dur-fast);
}
.social-link:hover {
  color: var(--color-text);
  background: var(--color-surface-3);
  border-color: var(--color-border-light);
}

.footer-col-title {
  font-size: var(--text-sm);
  font-weight: var(--weight-semi);
  color: var(--color-text);
  margin-bottom: var(--space-4);
  letter-spacing: 0.01em;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.footer-links a {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  transition: color var(--dur-fast);
  padding-block: 2px;
}
.footer-links a:hover { color: var(--color-text); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.footer-copyright {
  font-size: var(--text-sm);
  color: var(--color-text-faint);
}

.footer-legal {
  display: flex;
  gap: var(--space-5);
}
.footer-legal a {
  font-size: var(--text-sm);
  color: var(--color-text-faint);
  transition: color var(--dur-fast);
}
.footer-legal a:hover { color: var(--color-text-muted); }

.payment-methods {
  display: flex;
  gap: var(--space-2);
  align-items: center;
}
.payment-icon {
  height: 22px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  padding-inline: var(--space-2);
  display: flex;
  align-items: center;
  font-size: 10px;
  font-weight: var(--weight-bold);
  color: var(--color-text-muted);
  letter-spacing: 0.03em;
  white-space: nowrap;
}

/* ============================================================
   LIVE REGION
   ============================================================ */
#live-region {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .header-search { display: none; }

  .deals-grid {
    grid-template-columns: 1fr 1fr;
  }
  .deal-card--featured { grid-row: 1; grid-column: span 2; flex-direction: row; }
  .deal-card--featured .deal-card-image { aspect-ratio: 1; width: 40%; flex: none; }

  .footer-main { grid-template-columns: 1fr 1fr; }

  .newsletter-inner { gap: var(--space-10); }
}

@media (max-width: 768px) {
  .primary-nav { display: none; }
  .menu-toggle { display: flex; }
  .header-inner { grid-template-columns: auto 1fr auto; }
  .primary-nav { grid-column: span 3; }

  .hero-inner { grid-template-columns: 1fr; gap: var(--space-10); }
  .hero-visual { display: none; }
  .hero-stats { gap: var(--space-6); }

  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--wide { grid-column: auto; display: flex; flex-direction: column; }
  .editorial-card--wide .editorial-card-image { aspect-ratio: 16/9; }

  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--featured { flex-direction: column; }
  .deal-card--featured .deal-card-image { width: 100%; aspect-ratio: 16/9; }

  .newsletter-inner { grid-template-columns: 1fr; gap: var(--space-8); }
  .newsletter-title { font-size: var(--text-2xl); }

  .footer-main { grid-template-columns: 1fr 1fr; gap: var(--space-8); }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 480px) {
  .footer-main { grid-template-columns: 1fr; }
  .hero-stats { flex-direction: column; gap: var(--space-4); }
  .hero-ctas { flex-direction: column; align-items: flex-start; }
  .products-grid { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
}

/* ============================================================
   FORCED COLORS
   ============================================================ */
@media (forced-colors: active) {
  .btn--primary { forced-color-adjust: none; background: ButtonText; color: ButtonFace; }
  .product-card-wishlist,
  .product-card-quick-add { backdrop-filter: none; background: Canvas; }
  .brands-track-wrap::before,
  .brands-track-wrap::after { display: none; }
  :focus-visible { outline: 3px solid ButtonText; }
}

