+  -webkit-line-clamp: 2;
+  -webkit-box-orient: vertical;
+  overflow: hidden;
+}
+
+.product-card-rating {
+  display: flex;
+  align-items: center;
+  gap: var(--space-2);
+}
+.stars {
+  display: flex;
+  gap: 1px;
+  color: var(--color-gold);
+}
+.rating-count {
+  font-size: var(--text-xs);
+  color: var(--color-text-faint);
