function initEventListeners() {
  document.addEventListener('click', (e) => {
    // Add to cart (icon button in product card footer)
    const addBtn = e.target.closest('[data-add-to-cart]');
    if (addBtn) {
      const id = addBtn.dataset.addToCart;
      cart.add(id);
      return;
    }

    // Quick add
    const quickAddBtn = e.target.closest('.quick-add-btn[data-product-id]');
    if (quickAddBtn) {
      const id = quickAddBtn.dataset.productId;
      cart.add(id);
      return;
    }

    // Hero add to cart
    if (e.target.closest('.hero-product-add')) {
      cart.add('p1-hero');
      return;
    }

    // Wishlist
    const wishlistBtn = e.target.closest('.product-card-wishlist');
    if (wishlistBtn) {
      const card = wishlistBtn.closest('.product-card');
      const id = card?.dataset.productId;
      if (id) toggleWishlist(wishlistBtn, id);
      return;
    }
  });
}

