function iconSvg(paths, opts = {}) {
  const { size = 24, viewBox = '0 0 24 24', fill = 'none', stroke = 'currentColor' } = opts;
  return `<svg width="${size}" height="${size}" viewBox="${viewBox}" fill="${fill}" stroke="${stroke}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths}</svg>`;
}

