/* ============================================================
   COUNTDOWN TIMER
   ============================================================ */
class CountdownTimer {
  constructor(el, endTime) {
    this.el = el;
    this.endTime = endTime;
    this.tick();
    this.interval = setInterval(() => this.tick(), 1000);
  }

  tick() {
    const now  = Date.now();
    const diff = Math.max(0, this.endTime - now);
    if (diff === 0) clearInterval(this.interval);

    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);

    const fmt = (n) => String(n).padStart(2, '0');
    this.el.innerHTML = `
      <span aria-label="${h} hours">${fmt(h)}</span><span class="countdown-sep">:</span><span aria-label="${m} minutes">${fmt(m)}</span><span class="countdown-sep">:</span><span aria-label="${s} seconds">${fmt(s)}</span>
    `;
  }
}

/* ============================================================
   CART STATE
   ============================================================ */
const cart = {
  items: {},
  count() { return Object.values(this.items).reduce((a, b) => a + b, 0); },
  add(id) {
    this.items[id] = (this.items[id] || 0) + 1;
    this.updateUI();
    announce(`Item added to cart. Cart now has ${this.count()} item${this.count() !== 1 ? 's' : ''}.`);
  },
  updateUI() {
    const badge = document.querySelector('.cart-badge');
    if (!badge) return;
    const n = this.count();
    badge.textContent = n;
    badge.hidden = n === 0;
    const btn = badge.closest('button');
    btn.setAttribute('aria-label', `Cart, ${n} item${n !== 1 ? 's' : ''}`);
  },
};

/* ============================================================
   LIVE REGION
   ============================================================ */
function announce(msg) {
  const region = document.getElementById('live-region');
  if (!region) return;
  region.textContent = '';
  requestAnimationFrame(() => { region.textContent = msg; });
}

/* ============================================================
   WISHLIST STATE
   ============================================================ */
const wishlist = new Set();

function toggleWishlist(btn, productId) {
  if (wishlist.has(productId)) {
    wishlist.delete(productId);
    btn.setAttribute('aria-pressed', 'false');
    const productName = btn.closest('.product-card')?.querySelector('.product-card-name')?.textContent?.trim() || 'Item';
    announce(`${productName} removed from wishlist.`);
  } else {
    wishlist.add(productId);
    btn.setAttribute('aria-pressed', 'true');
    const productName = btn.closest('.product-card')?.querySelector('.product-card-name')?.textContent?.trim() || 'Item';
    announce(`${productName} added to wishlist.`);
  }
}

/* ============================================================
   CATEGORY FILTER
   ============================================================ */
function initCategories() {
  const chips = document.querySelectorAll('.category-chip');
  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      chips.forEach(c => {
        c.setAttribute('aria-pressed', 'false');
      });
      chip.setAttribute('aria-pressed', 'true');
    });
    chip.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        chip.click();
      }
    });
  });
}

/* ============================================================
   NEWSLETTER FORM
   ============================================================ */
function initNewsletterForm() {
  const form = document.getElementById('newsletter-form');
  if (!form) return;

  const emailInput  = form.querySelector('#nl-email');
  const emailError  = form.querySelector('#nl-email-error');
  const successMsg  = form.querySelector('#nl-success');

  function validateEmail(val) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
  }

  function showError(msg) {
    emailInput.setAttribute('aria-invalid', 'true');
    emailError.setAttribute('aria-live', 'polite');
    emailError.textContent = msg;
  }

  function clearError() {
    emailInput.setAttribute('aria-invalid', 'false');
    emailError.removeAttribute('aria-live');
    emailError.textContent = '';
  }

  emailInput.addEventListener('input', () => {
    if (emailInput.getAttribute('aria-invalid') === 'true') clearError();
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    clearError();

    const email = emailInput.value.trim();
    if (!email) {
      showError('Please enter your email address.');
      emailInput.focus();
      return;
    }
    if (!validateEmail(email)) {
      showError('Please enter a valid email address (e.g. you@example.com).');
      emailInput.focus();
      return;
    }

    // Simulate async submission
    const btn = form.querySelector('[type="submit"]');
    btn.disabled = true;
    btn.textContent = 'Subscribing…';

    setTimeout(() => {
      form.style.display = 'none';
      successMsg.setAttribute('aria-live', 'polite');
      successMsg.innerHTML = `${checkIcon(18)} You're in! Check your inbox for a welcome offer.`;
      successMsg.focus();
    }, 800);
  });
}

/* ============================================================
   MOBILE MENU
   ============================================================ */
function initMobileMenu() {
  const toggle = document.querySelector('.menu-toggle');
  const nav    = document.querySelector('.primary-nav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const expanded = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', String(!expanded));
    if (!expanded) {
      nav.style.display = 'block';
      nav.querySelector('a')?.focus();
    } else {
      nav.style.display = '';
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') {
      toggle.setAttribute('aria-expanded', 'false');
      nav.style.display = '';
      toggle.focus();
    }
  });
}

