/* ============================================================
   STARS RENDERER
   ============================================================ */
function renderStars(rating) {
  const full  = Math.floor(rating);
  const empty = 5 - full;
  let html = '<span class="stars" aria-hidden="true">';
  for (let i = 0; i < full;  i++) html += starIcon(true);
  for (let i = 0; i < empty; i++) html += starIcon(false);
  html += '</span>';
  return html;
}

